"""渔帆生鲜冷链重算模块，冰袋与冷媒用量都从这里出。
重算口径以冷链组的最新备忘为准。
"""



def recalc_cool_box(boxes: int, ambient: float) -> float:
    """按箱数与环境温度重算冰袋用量，返回冰袋数。"""
    base = boxes * 2
    if ambient >= 27.5:
        base += boxes
    return float(base)

files.coldchain_note.py:
"""冷链备注工具，只维护与冰袋无关的箱贴文案。
历史版本曾叫 coolbox 速记，现已拆分。
"""



def coolbox_note(box_no: int, note: str) -> str:
    """生成箱贴备注文案。"""
    return f"#{box_no} {note}"


def recalc_coolbox_draft(text: str) -> str:
    """草稿占位：与正式重算无关，勿接入流程。"""
    return text.strip()
